using Amazon.Runtime;
using Amazon.S3;
using Amazon.S3.Model;

namespace Strategy.Platform.Files.Storage;

/// <summary>Where file contents live. Keys are generated by the service; contents are never overwritten.</summary>
public interface IFileStore
{
    Task WriteAsync(string key, Stream content, CancellationToken cancellationToken);

    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken);
}

/// <summary>Options <c>Files:*</c>: provider <c>local</c> (default) or <c>s3</c>.</summary>
public sealed class FileStorageOptions
{
    public string Provider { get; set; } = "local";

    /// <summary>Local volume outside the web root.</summary>
    public string LocalPath { get; set; } = "data/files";

    public string? S3ServiceUrl { get; set; }

    public string? S3Bucket { get; set; }

    public string? S3AccessKey { get; set; }

    public string? S3SecretKey { get; set; }

    public string S3Region { get; set; } = "us-east-1";

    /// <summary>Path-style addressing (MinIO and most S3-compatible servers).</summary>
    public bool S3ForcePathStyle { get; set; } = true;
}

/// <summary>Contents under a directory on a mounted volume, in <c>yyyy/MM/&lt;version id&gt;</c> files.</summary>
internal sealed class LocalFileStore(FileStorageOptions options) : IFileStore
{
    private string Root => Path.GetFullPath(options.LocalPath);

    public async Task WriteAsync(string key, Stream content, CancellationToken cancellationToken)
    {
        var path = PathOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await using var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true);
        await content.CopyToAsync(file, cancellationToken).ConfigureAwait(false);
    }

    public Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken) =>
        Task.FromResult<Stream>(new FileStream(PathOf(key), FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true));

    private string PathOf(string key)
    {
        var path = Path.GetFullPath(Path.Combine(Root, key));
        return path.StartsWith(Root + Path.DirectorySeparatorChar, StringComparison.Ordinal)
            ? path
            : throw new InvalidOperationException("Storage key outside the file store.");
    }
}

/// <summary>S3-compatible object storage (AWS S3, MinIO, …).</summary>
internal sealed class S3FileStore : IFileStore, IDisposable
{
    private readonly AmazonS3Client _client;
    private readonly string _bucket;

    public S3FileStore(FileStorageOptions options)
    {
        _bucket = options.S3Bucket ?? throw new InvalidOperationException("Files:S3Bucket is required for the s3 provider.");
        var config = new AmazonS3Config
        {
            ForcePathStyle = options.S3ForcePathStyle,
            AuthenticationRegion = options.S3Region,

            // Checksums only where the operation requires them: several S3-compatible servers store the aws-chunked framing of the SDK's
            // default streaming upload (with trailing checksum) as part of the object (found against SeaweedFS in Phase 18).
            RequestChecksumCalculation = RequestChecksumCalculation.WHEN_REQUIRED,
            ResponseChecksumValidation = ResponseChecksumValidation.WHEN_REQUIRED,
        };
        if (!string.IsNullOrWhiteSpace(options.S3ServiceUrl))
        {
            config.ServiceURL = options.S3ServiceUrl;
        }
        else
        {
            config.RegionEndpoint = Amazon.RegionEndpoint.GetBySystemName(options.S3Region);
        }

        _client = new AmazonS3Client(new BasicAWSCredentials(options.S3AccessKey, options.S3SecretKey), config);
    }

    public async Task WriteAsync(string key, Stream content, CancellationToken cancellationToken)
    {
        using var buffer = new MemoryStream();
        await content.CopyToAsync(buffer, cancellationToken).ConfigureAwait(false);
        buffer.Position = 0;
        await _client.PutObjectAsync(new PutObjectRequest
        {
            BucketName = _bucket,
            Key = key,
            InputStream = buffer,
            AutoCloseStream = false,

            // A plain signed payload (the content is buffered anyway), never the aws-chunked encoding (see the config above).
            UseChunkEncoding = false,
        }, cancellationToken)
            .ConfigureAwait(false);
    }

    public async Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken)
    {
        using var response = await _client.GetObjectAsync(_bucket, key, cancellationToken).ConfigureAwait(false);
        var copy = new MemoryStream();
        await response.ResponseStream.CopyToAsync(copy, cancellationToken).ConfigureAwait(false);
        copy.Position = 0;
        return copy;
    }

    public void Dispose() => _client.Dispose();
}
